<script setup>
import { onMounted,reactive,ref } from 'vue'; import { api } from '../api';
const rows=ref([]),msg=ref(''),form=reactive({type:'VEHICLE_BREAKDOWN',severity:'HIGH',title:'',description:'',entityId:'DEL-1001',method:'WEB'}); async function load(){rows.value=(await api.get('/incidents')).data}onMounted(load);async function submit(){const {data}=await api.post('/incidents',form);msg.value=data.rectification;form.title='';form.description='';await load()}
</script>
<template><div class="split"><div><div class="section-head"><div><h3>Incident & exception center</h3><span>Automatic rectification rules create the next action</span></div></div><div class="card"><div class="list"><div class="list-item" v-for="i in rows" :key="i.id"><span class="dot"></span><div><b>{{i.title||i.type}}</b><span>{{i.description}}<br><strong>Rectification:</strong> {{i.rectification}}</span></div><span class="pill warn">{{i.status}}</span></div></div></div></div><div class="card modal-card"><h3 style="margin-top:0">Report an incident</h3><div class="form-grid"><div class="field"><label>Type</label><select v-model="form.type"><option>VEHICLE_BREAKDOWN</option><option>DRIVER_UNAVAILABLE</option><option>INVENTORY_MISMATCH</option><option>RETURN_GOODS</option><option>DAMAGED_GOODS</option><option>OTHER</option></select></div><div class="field"><label>Severity</label><select v-model="form.severity"><option>LOW</option><option>MEDIUM</option><option>HIGH</option><option>CRITICAL</option></select></div><div class="field"><label>Linked entity</label><input v-model="form.entityId" placeholder="e.g. DEL-1001"/></div><div class="field"><label>Title</label><input v-model="form.title"/></div><div class="field" style="grid-column:1/-1"><label>Description</label><textarea v-model="form.description"></textarea></div></div><button class="btn" @click="submit">Report & rectify</button><div v-if="msg" class="demo-accounts"><b>System action:</b> {{msg}}</div></div></div></template>
